local GuiService = game:GetService("GuiService")
local UserInputService = game:GetService("UserInputService")
local module = {}
module.CurrentAdapter = nil

local function getInputType()
    if GuiService:IsTenFootInterface() or UserInputService.GamepadEnabled then
        return "GameController"
    elseif UserInputService.TouchEnabled and not UserInputService.MouseEnabled then
        return "Touch"
    else
        return "KeyBoard"
    end
end

function module:Init(folder)
	local inputType = getInputType()
	if script:FindFirstChild(inputType) then
		local inputModule = require(script[inputType])
		module.CurrentAdapter = inputModule
		return inputModule:Init(folder)
	end
end

return module